<template><view class="page" v-if="alarm"><view class="hero"><view class="hero-top"><text class="type">{{alarm.alarmDescription||'设备告警'}}</text><text class="status" :class="alarm.handlingStatus?.toLowerCase()">{{statusText}}</text></view><text class="time">{{alarm.alarmTime||'-'}}</text></view><view class="card"><view v-for="row in rows" :key="row.label" class="row"><text class="label">{{row.label}}</text><text class="value">{{row.value||'-'}}</text></view></view><view v-if="alarm.handlingStatus!=='RESOLVED'&&alarm.handlingStatus!=='FALSE_ALARM'" class="handle"><text class="handle-title">告警处置</text><textarea v-model="note" class="note" maxlength="500" placeholder="填写现场情况或处置备注（可选）"/><view class="actions"><button v-if="alarm.handlingStatus==='PENDING'||!alarm.handlingStatus" class="ack" :loading="submitting" @click="submit('ACKNOWLEDGED')">确认告警</button><button class="false" :loading="submitting" @click="submit('FALSE_ALARM')">标记误报</button></view><button class="resolve" :loading="submitting" @click="submit('RESOLVED')">完成处置</button></view><view v-else class="result"><text>处置人：{{alarm.handledByName||'-'}}</text><text>处置时间：{{alarm.handledAt||'-'}}</text><text>处置备注：{{alarm.handlingNote||'-'}}</text></view><button v-if="alarm.deviceId&&alarm.channelId" class="live" @click="live">查看实时画面</button></view><view v-else class="loading">正在加载告警…</view></template>
<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{getAlarm,handleAlarm,type AlarmItem}from'@/api/alarm';import{showRequestError}from'@/utils/request';import{refreshMessageBadge}from'@/utils/message-badge';const id=ref(0),alarm=ref<AlarmItem>(),note=ref(''),submitting=ref(false);const statusText=computed(()=>({PENDING:'待处理',ACKNOWLEDGED:'已确认',RESOLVED:'已处理',FALSE_ALARM:'误报'}as Record<string,string>)[alarm.value?.handlingStatus||'PENDING']);const rows=computed(()=>[{label:'设备编号',value:alarm.value?.deviceId},{label:'通道编号',value:alarm.value?.channelId},{label:'告警等级',value:alarm.value?.alarmPriority?`${alarm.value.alarmPriority} 级`:''},{label:'告警方式',value:alarm.value?.alarmMethod},{label:'告警类型',value:alarm.value?.alarmType},{label:'经纬度',value:alarm.value?.longitude!=null?`${alarm.value.longitude}, ${alarm.value.latitude}`:''}]);async function load(){try{alarm.value=await getAlarm(id.value);note.value=alarm.value.handlingNote||''}catch(e){showRequestError(e)}}async function submit(status:'ACKNOWLEDGED'|'RESOLVED'|'FALSE_ALARM'){const labels={ACKNOWLEDGED:'确认这条告警',RESOLVED:'完成告警处置',FALSE_ALARM:'将这条告警标记为误报'};uni.showModal({title:'确认操作',content:labels[status],success:async r=>{if(!r.confirm)return;submitting.value=true;try{alarm.value=await handleAlarm(id.value,status,note.value.trim()||undefined);refreshMessageBadge();uni.showToast({title:'操作成功',icon:'success'})}catch(e){showRequestError(e)}finally{submitting.value=false}}})}function live(){if(!alarm.value)return;uni.navigateTo({url:`/pages/player/index?deviceId=${encodeURIComponent(alarm.value.deviceId||'')}&channelId=${encodeURIComponent(alarm.value.channelId||'')}&name=${encodeURIComponent(alarm.value.alarmDescription||'告警通道')}`})}onLoad(q=>{id.value=Number(q?.id||0);if(id.value)load();else uni.showToast({title:'告警ID无效',icon:'none'})})
</script><style scoped>.page{min-height:100vh;padding:24rpx;box-sizing:border-box}.hero,.card,.handle,.result{padding:32rpx;background:#fff;border-radius:24rpx}.hero-top{display:flex;align-items:center;justify-content:space-between}.type,.time,.result text{display:block}.type{font-size:36rpx;font-weight:700}.time{margin-top:14rpx;color:#7b8498;font-size:24rpx}.status{padding:8rpx 16rpx;border-radius:999rpx;font-size:22rpx;background:#ffead5;color:#b54708}.status.resolved{background:#e4f7ed;color:#14804a}.status.false_alarm{background:#edf0f5;color:#475467}.card,.handle,.result{margin-top:22rpx}.row{display:flex;justify-content:space-between;padding:22rpx 0;border-bottom:1rpx solid #edf0f5;font-size:26rpx}.label{color:#7b8498}.value{max-width:65%;word-break:break-all;text-align:right}.handle-title{font-size:30rpx;font-weight:600}.note{width:100%;height:150rpx;margin-top:22rpx;padding:22rpx;box-sizing:border-box;background:#f3f5f9;border-radius:18rpx;font-size:26rpx}.actions{display:flex;gap:18rpx;margin-top:22rpx}.actions button{flex:1}.ack,.resolve{color:#fff;background:#2368f2}.false{color:#b54708;background:#ffead5}.resolve{margin-top:18rpx}.result text{margin:10rpx 0;color:#667085;font-size:25rpx}.live{margin-top:28rpx;color:#fff;background:#172033;border-radius:18rpx}.loading{padding:100rpx;text-align:center;color:#8992a6}</style>
